import socket,json,pathlib
r=pathlib.Path.cwd();out={}
for name in ["allowed.sock","other.sock"]:
 s=socket.socket(socket.AF_UNIX);s.settimeout(2)
 try:s.connect(str(r/name));out[name]="connected"
 except OSError as e:out[name]=str(e)
 s.close()
for name in ["writable.txt",".git/blocked.txt"]:
 try:(r/name).write_text("probe");out[name]="written"
 except OSError as e:out[name]=str(e)
print(json.dumps(out))
